```rust
use std::sync::{mpsc::sync_channel, Arc, Mutex};

fn main() {
    // Shared lock used occasionally by both roles (R1).
    let lock = Arc::new(Mutex::new(()));

    // Rendezvous channels: sync_channel(0) requires both roles to meet (R2).
    // ch1: s -> r, ch2: r -> s (acknowledgement).
    let (ch1_tx, ch1_rx) = sync_channel::<i32>(0);
    let (ch2_tx, ch2_rx) = sync_channel::<i32>(0);

    // Sender role: s
    let lock_s = Arc::clone(&lock);
    let s = std::thread::spawn(move || {
        for _ in 0..3 {
            // Take the shared lock briefly, then release it BEFORE any
            // channel operation (R3: never wait on the channel while
            // holding the lock the other role needs).
            {
                let _guard = lock_s.lock().unwrap();
                // brief critical section, no channel ops here
            }
            // Lock is released; rendezvous send is now safe (R3, R4).
            ch1_tx.send(1).unwrap();

            // Wait for the receiver's acknowledgement, again without
            // holding the lock.
            let _ack = ch2_rx.recv().unwrap();
        }
    });

    // Receiver role: r
    let lock_r = Arc::clone(&lock);
    let r = std::thread::spawn(move || {
        let mut total = 0;
        for _ in 0..3 {
            // Take the shared lock briefly, then release it BEFORE any
            // channel operation (R3).
            {
                let _guard = lock_r.lock().unwrap();
                // brief critical section, no channel ops here
            }
            // Lock is released; rendezvous receive is now safe (R3, R4).
            let v = ch1_rx.recv().unwrap();
            total += v;

            // Acknowledge back to the sender over ch2.
            ch2_tx.send(v).unwrap();
        }
        total
    });

    // Both roles terminate on every schedule (R4).
    s.join().unwrap();
    let total = r.join().unwrap();

    let done = if total == 3 { 1 } else { 0 };
    // Exactly one line of output, then exit (R5).
    println!("DONE done={}", done);
}
```

Key design points:

- **R1**: `main` spawns two threads, `s` (sender) and `r` (receiver), which run concurrently and both take the shared `Mutex` a few times inside their loops.
- **R2**: `ch1` and `ch2` are `sync_channel(0)` rendezvous channels — a `send` only completes when the other side is `recv`-ing, so the roles must meet.
- **R3**: Each role acquires the lock in a scoped block that ends *before* any channel operation, so no role ever blocks on a channel while holding the lock the other role needs. This makes deadlock impossible regardless of interleaving.
- **R4**: The loops are symmetric (3 rounds each: send/ack for `s`, recv/ack for `r`), and since channel waits never overlap with lock holds, every schedule terminates with both threads joined.
- **R5**: The program prints exactly `DONE done=1` (computed from the received total) and exits.
